仅供课外学习使用，任何个人与机构不得利用此文章进行任何形式的作弊。A:A + B题目：描述：帅气的3C哥参加了一场考试，已知考试共五科，现知道他每科的成绩，求3C哥的总成绩。 输入：输入一行，输入5个整数，表示3C哥每科成绩，范围在[0, 100]内。 输出：输出一行，输出1个整数，表示3C哥的总成绩 输入样例1：198 95 87 100 90 输出样例1：1470 实例：1234567891011121314151617#include&lt;stdio.h&gt;#include&lt;stdlib.h&gt;#include&lt;math.h&gt;#include&lt;string.h&gt;#include&lt;windows.h&gt;int main()&#123; int a[5]; int i,sum=0; for(i=0;i&lt;5;i++) &#123; scanf(&quot;%d&quot;,&amp;a[i]); sum+=a[i]; &#125; printf(&quot;%d&quot;,sum); return 0;&#125; B:3n + 1问题题目：描述：对于任意大于1的自然数n，若n为奇数，则将n变为3n+1，否则变为n的一半；经过若干次这样的变换，一定会使n变为1。比如： 3-&gt;10-&gt;5-&gt;16-&gt;8-&gt;4-&gt;2-&gt;1 要求：输入n，输出变换的次数。 输入：输入一行，输入一个正整数n，1 &lt;&#x3D; n &lt;&#x3D; 100。 输出：输出一行，输出一个正整数，表示变换的次数。 输入样例1：13 输出样例1：17 实例：12345678910111213141516171819202122232425#include&lt;stdio.h&gt;#include&lt;stdlib.h&gt;#include&lt;math.h&gt;#include&lt;string.h&gt;#include&lt;windows.h&gt;int main()&#123; int n,cnt=0; scanf(&quot;%d&quot;,&amp;n); for(;n!=1;) &#123; if(n%2==1) &#123; n = 3*n+1; cnt++; &#125; else &#123; n = n/2; cnt++; &#125; &#125; printf(&quot;%d&quot;,cnt); return 0; &#125; C:稀疏矩阵题目：描述：大部分元素为0的矩阵称为稀疏矩阵。假设有k个非0元素，则可把稀疏矩阵用k*3的矩阵简记之，其中第一列为行号，第二列为列号，第三列是该行、该列下的非0元素的值。 输入：首先输入一行，输入两个正整数，表示稀疏矩阵的行号和列号，再输入一个稀疏矩阵，行和列不超过100。 输出：输出它的简记形式，按从上到下，从左到右的顺序依次输出。每一行输出3个整数，每两个整数之间一个空格，最后一个整数后面没有空格。 输入样例1：12343 40 0 0 50 2 0 00 1 0 0 输出样例1：1231 4 5 2 2 2 3 2 1 实例：1234567891011121314151617181920212223242526272829303132333435363738394041#include&lt;stdio.h&gt;#include&lt;stdlib.h&gt;#include&lt;math.h&gt;#include&lt;string.h&gt;#include&lt;windows.h&gt;int main()&#123; int m,n; int i,k; int cnt[100][100],ret[100][100],t[100][100]; for(i=0;i&lt;100;i++) for(k=0;k&lt;100;k++) &#123; cnt[i][k]=0; t[i][k]=0; &#125; scanf(&quot;%d%d&quot;,&amp;m,&amp;n); int a[100][100]; for(i=0;i&lt;m;i++) for(k=0;k&lt;n;k++) scanf(&quot;%d&quot;,&amp;a[i][k]); for(i=0;i&lt;m;i++) &#123; int temp = 0; for(k=0;k&lt;n;k++) &#123; if(a[i][k]==0) &#123; cnt[i][temp]++; &#125; else &#123; cnt[i][temp]++; printf(&quot;%d %d %d
&quot;,i+1,cnt[i][temp],a[i][k]); temp++; cnt[i][temp] = cnt[i][temp-1]; &#125; &#125; &#125; return 0;&#125; D:开灯问题题目：描述：有n盏灯，编号为1~n。第1个人把所有灯打开，第2个人按下所有编号为2的倍数的开关（这些灯将被关掉），第3个人按下所有编号为3的倍数的开关（其中关掉的灯将被打开，开着的灯将被关闭），以此类推。一共有k个人，问最后有哪些灯开着？ 输入：输入一行，输入两个正整数n和k。(k&lt;&#x3D;n&lt;&#x3D;1000） 输出：输出一行，输出所有开着的灯的编号，每个编号后面跟一个空格。 输入样例1：7 3 输出样例1：1 5 6 7 提示：可先使用string.h里的memset函数将数组全部置0；使用C语言的逻辑非(!)操作符 实例：12345678910111213141516171819202122232425262728293031323334#include&lt;stdio.h&gt;#include&lt;stdlib.h&gt;#include&lt;math.h&gt;#include&lt;string.h&gt;#include&lt;windows.h&gt;int main()&#123; //没有用提示，但不扣分 int n,k; scanf(&quot;%d%d&quot;,&amp;n,&amp;k); int a[1000],b[1000]; int i,m,t=2; for(i=0;i&lt;n;i++) &#123; a[i] = 0; b[i] = i+1; &#125; for(i=0;i&lt;k-1;i++) &#123; for(m=0;m&lt;n;m++) if(b[m]%t==0) &#123; if(a[m]==1) a[m]=0; else a[m]=1; &#125; t++; &#125; for(i=0;i&lt;n;i++) if(a[i]!=1) printf(&quot;%d &quot;,b[i]); return 0;&#125; E:还是一个不妖艳的问题题目：描述：U君与S君想测试下双方的缘分，测试规则是两人各想一个数字，如果两个数字互质则代表有缘分。 输入：多组测试,每组测试输入两个数字m和n(m和n均不超过int取值范围)，空格隔开。 输出：对于每组，如果有缘分的话，输出“Yes”；否则，输出“No” 输入样例1：1210 517 13 输出样例1：12NoYes 提示：可使用 while (scanf(“%d%d”, &amp;n, &amp;m) !&#x3D; EOF) 完成多组输入 实例：12345678910111213141516171819202122232425262728293031#include&lt;stdio.h&gt;#include&lt;stdlib.h&gt;#include&lt;math.h&gt;#include&lt;string.h&gt;#include&lt;windows.h&gt;int gcd(int m,int n)&#123; while(n^=m^=n^=m%=n); return m;&#125; int main()&#123; int m,n; while(scanf(&quot;%d%d&quot;,&amp;m,&amp;n)!=EOF) &#123; if(m&lt;n) &#123; int temp = m; m = n; n = temp; &#125; int t=gcd(m,n); if(t==1) printf(&quot;Yes
&quot;); else printf(&quot;No
&quot;); &#125; return 0; &#125; F:回文串的排序题目：描述：输入n个字符串，将其中是回文串的字符串，按照长度从小到大的顺序输出，如果长度相同，则按照输入的顺序输出即可。 回文的含义是：正着看和倒着看相同，如abba和yyxyy。 输入：第一行首先是一个整数n（n&lt;50），表示有n个字符串（每个字符串的都长度小于100）。接下来有n行，每行输入一个字符串。 输出：按照长度从小到大的顺序输出其中的回文串，如果长度相同，则按照输入的顺序输出。 输入样例1：123454abbbabccbaabbaacca 输出样例1：123abbaaccaabccba 实例：123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960#include&lt;stdio.h&gt;#include&lt;stdlib.h&gt;#include&lt;math.h&gt;#include&lt;string.h&gt;#include&lt;windows.h&gt;class huiwen&#123; public: char a[100];&#125;store[50]; int main()&#123; int n,i,k,cnt=0; scanf(&quot;%d&quot;,&amp;n); char temp[100]; for(i=0;i&lt;n;i++) &#123; int ret = 0; int k; scanf(&quot;%s&quot;,temp); int left = 0; int right = strlen(temp)-1; for(;;left++) &#123; if(temp[left]!=temp[right]) break; else ret++; if(ret==(strlen(temp)/2)) &#123; strcpy(store[cnt].a,temp); cnt++; &#125; if(right%2==0) if(right-left==1) break; if(right%2!=0) if(right==left) break; right--; &#125; &#125; for(i=0;i&lt;cnt;i++) for(k=0;k&lt;cnt-i-1;k++) if(strlen(store[k].a)&gt;strlen(store[k+1].a)) &#123; char s[100]; strcpy(s,store[k].a); strcpy(store[k].a,store[k+1].a); strcpy(store[k+1].a,s); &#125; for(i=0;i&lt;cnt;i++) puts(store[i].a); return 0;&#125; G:蛇形填数题目：描述：在nn方阵里填入1,2,…,nn，要求填成蛇形。例如n&#x3D;4时方阵为： 10 11 12 1 9 16 13 2 8 15 14 3 7 6 5 4 输入：本题为多组输入。每组数据输入一行，输入一个正整数n。n&lt;&#x3D;8。 输出：输出n*n的蛇形矩阵，每行中每两个数之间用一个空格隔开，每行最后一个数后面没有空格。 输入样例1：14 输出样例1：123410 11 12 19 16 13 28 15 14 37 6 5 4 实例：1234567891011121314151617181920212223242526272829303132333435363738394041424344454647#include&lt;stdio.h&gt;#include&lt;stdlib.h&gt;#include&lt;math.h&gt;#include&lt;string.h&gt;#include&lt;windows.h&gt;int main()&#123; int n; while(scanf(&quot;%d&quot;,&amp;n)!=EOF) &#123; int count=1; int a[8][8]; int i,j,t=0; while(count&lt;=n*n) &#123; for(i=n-1-t,j=0+t;j&lt;n-1-t;j++) a[j][i] = count++; if(count&gt;=n*n) break; for(i=n-1-t,j=n-1-t;i&gt;0+t;i--) a[j][i] = count++; if(count&gt;=n*n) break; for(i=0+t,j=n-1-t;j&gt;0+t;j--) a[j][i] = count++; if(count&gt;=n*n) break; for(i=0+t,j=0+t;i&lt;n-1-t;i++) a[j][i] = count++; if(count&gt;=n*n) break; t++; &#125; a[(n-1)/2][(n-1)/2] = n*n; int x,y; for(x = 0; x &lt; n; x++) &#123; for(y = 0; y &lt; n; y++) &#123; if(y!=n-1) printf(&quot;%d &quot;, a[x][y]); else printf(&quot;%d&quot;, a[x][y]); &#125; printf(&quot;
&quot;); &#125;&#125; return 0; &#125;

目录 CloudComPy介绍 CloudComPy介绍简单来说，CloudComPy通过Python接口，调用点云操作软件CloudCompare的一些功能。 官方文档：CloudComPy官方文档https://www.simulation.openfields.fr/documentation/CloudComPy/html/ 环境配置必须在pt310及以上版本使用，最好部署在anaconda环境下。具体可以参考这篇CSDN博客：windows平台cloudcompy安装https://blog.csdn.net/sljsxy/article/details/146494374 注意win7是不支持pt310版本的，如果非要使用，网上有适用于win7版本的pt310包，至于环境和包会不会起冲突则未加实验过。 项目代码项目包含了测试样例生成、手动选择三点作为粗配准、ICP细配准，以及配准可视化的模块，每个模块都可以单独使用。 环境配置与依赖检查基于上一章环境配置所述环境，另外安装适合版本的open3d即可。如果需要图形化界面，则需要安装PyQt5（后续会更新图形化界面版本的软件）。 12345678910111213141516171819202122import open3d as o3dimport numpy as npimport copyimport osimport sysSCIPY_AVAILABLE = FalseCLOUDCOMPY_AVAILABLE = Falsetry: from scipy.spatial import cKDTree SCIPY_AVAILABLE = Trueexcept ImportError: passtry: import cloudComPy as cc CLOUDCOMPY_AVAILABLE = Trueexcept ImportError: pass 基础工具12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849def load_ply(file_path): &quot;&quot;&quot;读取点云，支持PLY/Mesh自动转换&quot;&quot;&quot; if not os.path.exists(file_path): print(f&quot;[错误] 文件不存在: &#123;file_path&#125;&quot;) return None pcd = o3d.io.read_point_cloud(file_path) if len(pcd.points) == 0: mesh = o3d.io.read_triangle_mesh(file_path) pcd = o3d.geometry.PointCloud() pcd.points = mesh.vertices if mesh.has_vertex_normals(): pcd.normals = mesh.vertex_normals pcd.remove_non_finite_points() return pcddef save_ply(pcd, file_path): o3d.io.write_point_cloud(file_path, pcd, write_ascii=True)def generate_random_transform(): &quot;&quot;&quot;生成随机变换矩阵及其逆矩阵(GT)&quot;&quot;&quot; angle = 0.25 * np.pi r_xyz = np.random.uniform(-angle, angle, 3) t_xyz = np.random.uniform(-100, 100, 3) R = o3d.geometry.get_rotation_matrix_from_xyz(r_xyz) T = np.eye(4) T[:3, :3] = R T[:3, 3] = t_xyz return T, np.linalg.inv(T) # 返回: 扰动矩阵, 还原矩阵(GT)def get_downsampled_pcd(pcd, target_count=10000): &quot;&quot;&quot;自适应降采样&quot;&quot;&quot; if len(pcd.points) &lt;= target_count: return copy.deepcopy(pcd) bbox = pcd.get_axis_aligned_bounding_box() voxel_size = max(bbox.get_extent()) / 50.0 pcd_down = pcd.voxel_down_sample(voxel_size) # 简单迭代确保点数适中 while len(pcd_down.points) &gt; target_count * 1.5: voxel_size *= 1.5 pcd_down = pcd.voxel_down_sample(voxel_size) return pcd_down 矩阵误差分析1234567891011121314151617181920212223242526272829303132333435363738def calculate_matrix_error(T_est, T_gt): &quot;&quot;&quot; 比较估计矩阵与参考矩阵的平移和旋转误差 :param T_est: 算法计算出的最终变换矩阵 (4x4) :param T_gt: 真值矩阵 (Ground Truth) (4x4) &quot;&quot;&quot; print(&quot;
&quot; + &quot;=&quot; * 20 + &quot; 矩阵精度分析 &quot; + &quot;=&quot; * 20) # 1. 平移误差 (欧氏距离) t_est = T_est[:3, 3] t_gt = T_gt[:3, 3] trans_error = np.linalg.norm(t_est - t_gt) # 2. 旋转误差 (Geodesic distance on SO(3)) R_est = T_est[:3, :3] R_gt = T_gt[:3, :3] # R_diff = R_est * R_gt^T R_diff = np.dot(R_est, R_gt.T) trace = np.trace(R_diff) # 限制数值范围在 [-1, 1] 避免数值噪音导致的 NaN val = (trace - 1) / 2.0 val = np.clip(val, -1.0, 1.0) rot_error_rad = np.arccos(val) rot_error_deg = np.degrees(rot_error_rad) print(f&quot;平移误差 (Translation Error): &#123;trans_error:.6f&#125;&quot;) print(f&quot;旋转误差 (Rotation Error): &#123;rot_error_deg:.6f&#125; 度&quot;) print(&quot;
--- 矩阵详情 ---&quot;) print(&quot;Estimated Matrix:
&quot;, T_est) print(&quot;Ground Truth Matrix:
&quot;, T_gt) print(&quot;Diff (Est - GT):
&quot;, T_est - T_gt) return trans_error, rot_error_deg 配准流程12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970def manual_registration(source, target): &quot;&quot;&quot;手动粗配准：左右分屏选点&quot;&quot;&quot; print(&quot;
&gt;&gt;&gt; 开始手动粗配准 (请在两窗口选至少3个对应点，Shift+左键)&quot;) src_vis = get_downsampled_pcd(source) tgt_vis = get_downsampled_pcd(target) src_vis.paint_uniform_color([1, 0.706, 0]) # 橙 (Source) tgt_vis.paint_uniform_color([0, 0.651, 0.929]) # 蓝 (Target) # 偏移显示 Source tgt_bbox = tgt_vis.get_axis_aligned_bounding_box() offset = tgt_bbox.get_extent()[0] * 1.5 + 50.0 shift_vec = (tgt_bbox.get_center() - src_vis.get_center()) + [offset, 0, 0] src_vis.translate(shift_vec) vis = o3d.visualization.VisualizerWithEditing() vis.create_window(window_name=&#x27;选点: 左目标(蓝) - 右源(橙)&#x27;, width=1280, height=720) vis.add_geometry(src_vis + tgt_vis) vis.run() vis.destroy_window() indices = vis.get_picked_points() pts_s, pts_t = [], [] points_all = np.asarray((src_vis + tgt_vis).points) len_tgt = len(tgt_vis.points) for idx in indices: p = points_all[idx] if idx &lt; len_tgt: pts_t.append(p) else: pts_s.append(p - shift_vec) # 还原坐标 min_k = min(len(pts_s), len(pts_t)) if min_k &lt; 3: print(&quot;[警告] 选点不足3对，跳过粗配准。&quot;) return np.eye(4) print(f&quot;使用 &#123;min_k&#125; 对点进行计算...&quot;) pcd_s = o3d.geometry.PointCloud(o3d.utility.Vector3dVector(pts_s[:min_k])) pcd_t = o3d.geometry.PointCloud(o3d.utility.Vector3dVector(pts_t[:min_k])) corr = o3d.utility.Vector2iVector([[i, i] for i in range(min_k)]) reg = o3d.pipelines.registration.TransformationEstimationPointToPoint() return reg.compute_transformation(pcd_s, pcd_t, corr)def run_icp(source_path, target_path): &quot;&quot;&quot;调用 CloudComPy 进行 ICP&quot;&quot;&quot; if not CLOUDCOMPY_AVAILABLE: print(&quot;[跳过] 未检测到 cloudComPy，仅使用粗配准结果。&quot;) return np.eye(4) print(&quot;
&gt;&gt;&gt; 执行 CloudComPy ICP 精配准...&quot;) try: cc_src = cc.loadPointCloud(source_path) cc_tgt = cc.loadPointCloud(target_path) # 参数: overlap=0.8, threads=auto, etc. res = cc.ICP(cc_src, cc_tgt, 1.0e-6, 50, 50000, True, cc.CONVERGENCE_TYPE.MAX_ERROR_CONVERGENCE, False, 0.8) mat = [] for line in res.transMat.toString().strip().split(&#x27;
&#x27;): if line.strip(): mat.append([float(x) for x in line.split()]) return np.array(mat) except Exception as e: print(f&quot;[ICP 错误] &#123;e&#125;&quot;) return np.eye(4) 结果可视化12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455def visualize_heatmap_on_target(source, target, limit=5.0): print(&quot;
&gt;&gt;&gt; 生成误差色谱 (基准: 目标点云)&quot;) if not target.has_normals(): target.estimate_normals() target.orient_normals_consistent_tangent_plane(50) src_pts = np.asarray(source.points) tgt_pts = np.asarray(target.points) tgt_nrm = np.asarray(target.normals) dists, signed_dists = np.zeros(len(tgt_pts)), np.zeros(len(tgt_pts)) if SCIPY_AVAILABLE: tree = cKDTree(src_pts) dists, idxs = tree.query(tgt_pts, k=1, workers=-1) nearest_pts = src_pts[idxs] diff_vec = nearest_pts - tgt_pts # 投影距离：(源-目标) 点乘 目标法线 signed_dists = np.einsum(&#x27;ij,ij-&gt;i&#x27;, diff_vec, tgt_nrm) else: print(&quot;未安装 Scipy，仅显示绝对距离。&quot;) dists = np.asarray(target.compute_point_cloud_distance(source)) signed_dists = dists # 渲染颜色: 红(+), 蓝(-), 绿(0) colors = np.zeros((len(tgt_pts), 3)) colors[:, 1] = 1.0 # 默认绿 # 正偏差 (Source 在 Target 法线方向外侧) -&gt; 红 mask_pos = signed_dists &gt; 0 if np.any(mask_pos): norm_val = np.clip(signed_dists[mask_pos] / limit, 0, 1) colors[mask_pos, 0] = norm_val colors[mask_pos, 1] = 1.0 - norm_val colors[mask_pos, 2] = 0 # 负偏差 (Source 在 Target 法线方向内侧) -&gt; 蓝 mask_neg = signed_dists &lt; 0 if np.any(mask_neg): norm_val = np.clip(np.abs(signed_dists[mask_neg]) / limit, 0, 1) colors[mask_neg, 0] = 0 colors[mask_neg, 1] = 1.0 - norm_val colors[mask_neg, 2] = norm_val vis_pcd = copy.deepcopy(target) vis_pcd.colors = o3d.utility.Vector3dVector(colors) stat_msg = f&quot;Abs Mean: &#123;np.mean(np.abs(signed_dists)):.4f&#125;, Max: &#123;np.max(signed_dists):.4f&#125;&quot; print(stat_msg) o3d.visualization.draw_geometries([vis_pcd], window_name=f&quot;偏差分析 (阈值 &#123;limit&#125;)&quot;, width=1024, height=768, left=50, top=50) 主程序123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263def main(): # 路径配置 work_dir = r&quot;&quot; target_ply = os.path.join(work_dir, &quot;.ply&quot;) # 目标 (Standard) source_ply = os.path.join(work_dir, &quot;.ply&quot;) # 源 (待配准) out_dir = os.path.join(work_dir, &quot;results&quot;) os.makedirs(